package ama.transcript;

import ama.access.MeetingAccess;
import ama.config.*;
import ama.contract.ConfigArchiveContracts.Ref;
import ama.contract.IdentityContracts.Actor;
import ama.contract.MinutesContracts.*;
import ama.minutes.*;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.util.function.Supplier;
import static ama.contract.MinutesContracts.*;
import static ama.contract.MinutesContracts.FailureCode.*;

/** Owner-private projections. Metadata does not assert archived graph validity; details use S/A/F. */
public final class JdbcMinutesQueries {
 private final JdbcTranscriptAuthority authority;private final JdbcTemplate j;private final JdbcMinutesFactsReader reader;private final Supplier<ConfigArchiveSource.Snapshot> archives;private final String pin;private final Ref prompt,model;private final TranscriptAcquisitionBudget limits;private MinutesEditorRuntime combined;private JdbcMinutesInitialSettings initial;private JdbcMinutesGenerationCommands generation;
 public JdbcMinutesQueries(JdbcTranscriptAuthority authority,Supplier<ConfigArchiveSource.Snapshot> archives,String pin,Ref prompt,Ref model,TranscriptAcquisitionBudget limits){this.authority=authority;this.pin=pin;this.limits=limits;this.archives=archives;this.prompt=prompt;this.model=model;j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);reader=new JdbcMinutesFactsReader(authority,archives,pin,limits);}
 void bindCombined(MinutesEditorRuntime editor,JdbcMinutesInitialSettings initial,JdbcMinutesGenerationCommands generation){if(combined!=null)throw new IllegalStateException("Duplicate combined projections");editor.requireCombined(initial,generation,this);this.combined=editor;this.initial=initial;this.generation=generation;}
 void requireConfiguration(JdbcTranscriptAuthority expected,Supplier<ConfigArchiveSource.Snapshot> archives,String pin,Ref prompt,Ref model,TranscriptAcquisitionBudget limits){if(authority!=expected||this.archives!=archives||!this.pin.equals(pin)||!this.prompt.equals(prompt)||!this.model.equals(model)||!this.limits.equals(limits))throw new IllegalArgumentException("Foreign minutes projections");}
 public Map<String,Object> templates(Actor actor,String meeting,int limit,String after){
  page(limit);if(after!=null)uuid(after);MinutesCatalogAdmission.Selection selection=null;RuntimeException error=null;try{selection=MinutesCatalogAdmission.capture(archives.get(),prompt,model,authority.readBudget());}catch(RuntimeException unavailable){error=unavailable;}
  if(error!=null){authorize(actor,meeting);throw error;}var snapshot=reader.readOwner(actor,meeting,"INITIAL_SETTINGS",selection.defaultTemplateRevisionId());var revision=JdbcMinutesFactsReader.one(snapshot.graph(),Table.TEMPLATE_REVISION,selection.defaultTemplateRevisionId());var parents=snapshot.graph().auxiliary().getOrDefault("minutes_template",List.of());require(parents.size()==1,PROVENANCE_UNAVAILABLE);var parent=parents.getFirst();require(revision.nullableString("owner_id")==null&&parent.get("owner_id")==null&&revision.string("template_id").equals(parent.get("id"))&&revision.string("id").equals(parent.get("current_revision_id"))&&revision.number("revision")==1&&revision.number("theme_count")==7&&ControlledMinutesTemplateInstaller.NAME.equals(revision.string("name"))&&ControlledMinutesTemplateInstaller.THEMES.equals(revision.string("themes")),PROFILE_UNAVAILABLE);
  var item=Map.<String,Object>of("templateId",revision.string("template_id"),"revisionId",revision.string("id"),"name",revision.string("name"),"themes",Arrays.stream(Category.values()).map(Enum::name).toList(),"themeCount",7,"selectable",true,"default",true);boolean include=after==null||revision.string("template_id").compareTo(after)>0;return map("items",include?List.of(item):List.of(),"nextCursor",null,"observation",observation(snapshot));
 }
 public Map<String,Object> current(Actor actor,String meeting){var budget=requestBudget();var snapshot=reader.readOwner(actor,meeting,"CURRENT_GENERATION",null,budget);var root=snapshot.observation();var tasks=new MinutesMetadataPages(authority,limits).allTaskRows(actor,meeting,budget);var active=tasks.stream().filter(t->Set.of("READY","RUNNING","RECONCILING").contains(t.get("state"))).map(t->t.get("id")).toList();var eligibility=readiness(actor,meeting,((Number)root.get("revision")).longValue(),null,"eligible",budget);return map("saved",map("transcriptConfirmationId",root.get("transcript_confirmation_id"),"templateRevisionId",root.get("template_revision_id"),"exclusionRevisionId",root.get("exclusion_revision_id"),"elementSetId",root.get("element_set_id")),"scope","FULL","materials","EMPTY","activeTaskIds",active,"eligible",eligibility.get("eligible"),"reasons",eligibility.get("reasons"),"observation",observation(snapshot));}
 public Map<String,Object> input(Actor actor,String meeting,String input){uuid(input);var budget=requestBudget();var snapshot=reader.readOwner(actor,meeting,"STORED_INPUT",input,budget);var selected=JdbcMinutesFactsReader.one(snapshot.graph(),Table.GENERATION_INPUT,input);return map("input",project(selected),"manifestJson",snapshot.generationManifestJson(input),"profiles",snapshot.roots().stream().map(r->Map.of("artifactType",r.artifactType().name(),"version",r.version(),"sha256",r.sha256())).toList(),"provenanceVerified",true,"currentReadiness",readiness(actor,meeting,currentRevision(actor,meeting,budget),null,"eligible",budget),"observation",observation(snapshot));}
 public Map<String,Object> task(Actor actor,String meeting,String task){uuid(task);var rows=taskRows(actor,meeting).stream().filter(t->task.equals(t.get("id"))).toList();require(rows.size()==1,PROVENANCE_UNAVAILABLE);var row=rows.getFirst();var snapshot=reader.readOwner(actor,meeting,"STORED_INPUT",(String)row.get("input_id"));var actual=snapshot.graph().auxiliary().getOrDefault("durable_task",List.of()).stream().filter(t->task.equals(t.get("id"))).toList();require(actual.size()==1,PROVENANCE_UNAVAILABLE);var candidates=snapshot.graph().auxiliary().getOrDefault("generation_candidate",List.of()).stream().filter(c->task.equals(c.get("task_id"))).toList();require(candidates.size()<=1,PROVENANCE_UNAVAILABLE);var executions=snapshot.graph().auxiliary().getOrDefault("external_execution",List.of()).stream().filter(e->task.equals(e.get("task_id"))).toList();require(executions.size()<=1,PROVENANCE_UNAVAILABLE);var attempts=snapshot.graph().auxiliary().getOrDefault("task_attempt",List.of()).stream().filter(a->task.equals(a.get("task_id"))).map(a->map("attemptToken",token(a.get("attempt")),"outcome",a.get("outcome"),"errorCode",a.get("error_code"),"startedAt",a.get("started_at"),"endedAt",a.get("ended_at"))).toList();return map("task",taskProjection(actual.getFirst()),"attempts",attempts,"remoteOutcome",executions.isEmpty()?"NOT_MARKED":executions.getFirst().get("state"),"localOutcome",actual.getFirst().get("state"),"candidateId",candidates.isEmpty()?null:candidates.getFirst().get("id"),"allowedActions",List.of("INSPECT"),"observation",observation(snapshot));}
 public Map<String,Object> tasks(Actor actor,String meeting,int limit,String cursor){return new MinutesMetadataPages(authority,limits).page(actor,meeting,limit,"TASKS",cursor);}
 public Map<String,Object> candidates(Actor actor,String meeting,int limit,String state,String cursor){require(Set.of("PENDING","ADOPTED","REJECTED","STALE","ALL").contains(state),INVALID_ARGUMENT);return new MinutesMetadataPages(authority,limits).page(actor,meeting,limit,"CANDIDATES:"+state,cursor);}
 public Map<String,Object> candidate(Actor actor,String meeting,String candidate){uuid(candidate);var budget=requestBudget();var snapshot=reader.readOwner(actor,meeting,"CANDIDATE",candidate,budget);var selected=snapshot.graph().auxiliary().getOrDefault("generation_candidate",List.of()).stream().filter(c->candidate.equals(c.get("id"))).toList();require(selected.size()==1,PROVENANCE_UNAVAILABLE);var included=Set.of(Table.MINUTES_REVISION,Table.ELEMENT_SET,Table.MINUTES_ELEMENT,Table.ACTION_ITEM,Table.ACTION_SUGGESTION,Table.SENSITIVE_DETECTION,Table.BACKGROUND_NOTE,Table.SOURCE_LOCATOR,Table.SENSITIVE_DETECTION_SOURCE,Table.BACKGROUND_NOTE_SOURCE,Table.EVIDENCE_LINK);var tables=new TreeMap<String,Object>();for(var table:included)tables.put(table.sqlName(),snapshot.facts().rows().stream().filter(row->row.table()==table).map(JdbcMinutesQueries::project).toList());return map("candidate",candidateProjection(selected.getFirst()),"graph",tables,"provenanceVerified",true,"eligibility",readiness(actor,meeting,null,candidate,"canAdopt",budget),"observation",observation(snapshot));}
 private TranscriptAcquisitionBudget.Ledger requestBudget(){return limits.ledger(authority.readBudget(),authority.canonicalBudget(),()->false);}
 private long currentRevision(Actor actor,String meeting,TranscriptAcquisitionBudget.Ledger budget){budget.row(1);return authority.transactionRunner().required(()->{authority.fileRegistry().lock(actor,meeting,MeetingAccess.Action.EDIT);return j.queryForObject("SELECT revision FROM meeting WHERE id=?",Long.class,meeting);});}
 private Map<String,Object> readiness(Actor actor,String meeting,Long revision,String candidate,String field,TranscriptAcquisitionBudget.Ledger budget){
  if(combined==null){authorize(actor,meeting);return map(field,false,"reasons",List.of("MINUTES_COMBINED_NOT_INSTALLED"));}
  try{combined.requireCombined(initial,generation,this);}catch(IllegalArgumentException|IllegalStateException|Failure unavailable){authorize(actor,meeting);return map(field,false,"reasons",List.of("MINUTES_COMBINED_NOT_INSTALLED"));}
  try{if(candidate==null)generation.verifyCurrentReadiness(actor,meeting,revision,budget);else combined.saved().verifyAdoptionReadiness(actor,meeting,candidate,budget);return map(field,true,"reasons",List.of());}
  catch(Failure unavailable){if(unavailable.code()==CANCELLED)throw unavailable;authorize(actor,meeting);return map(field,false,"reasons",List.of(unavailable.code().name()));}
  catch(ama.contract.TranscriptContracts.Failure unavailable){if(!Set.of(409,422,503).contains(unavailable.status()))throw unavailable;authorize(actor,meeting);return map(field,false,"reasons",List.of(unavailable.code()));}
 }
 private List<Map<String,Object>> taskRows(Actor actor,String meeting){return new MinutesMetadataPages(authority,limits).allTaskRows(actor,meeting);}

 static Map<String,Object> taskProjection(Map<String,Object> row){return map("taskId",row.get("id"),"inputId",row.get("input_id"),"inputFingerprint",row.get("input_fingerprint"),"businessVersionToken",token(row.get("business_version")),"cancelEpochToken",token(row.get("cancel_epoch")),"state",row.get("state"),"errorCode",row.get("last_error"),"outputKind",row.get("output_kind"),"outputId",row.get("output_id"),"attemptToken",token(row.get("attempt")));}
 static Map<String,Object> candidateProjection(Map<String,Object> row){return map("candidateId",row.get("id"),"inputId",row.get("input_id"),"taskId",row.get("task_id"),"minutesRevisionId",row.get("minutes_revision_id"),"elementSetId",row.get("element_set_id"),"baseRevisionToken",token(row.get("base_revision")),"inputFingerprint",row.get("input_fingerprint"),"state",row.get("state"),"createdAt",token(row.get("created_at")),"decidedAt",token(row.get("decided_at")));}
 private void authorize(Actor actor,String meeting){authority.transactionRunner().required(()->{authority.fileRegistry().lock(actor,meeting,MeetingAccess.Action.EDIT);return null;});}
 private static Map<String,Object> observation(JdbcMinutesFactsReader.Snapshot snapshot){return JdbcMinutesSettingsReceipts.observation(snapshot.observation());}
 private static String token(Object value){return value==null?null:value.toString();}
 private static Map<String,Object> project(FullRow row){var out=new LinkedHashMap<String,Object>();for(int n=0;n<row.cells().size();n++){var column=row.table().columns().get(n);var cell=row.cells().get(n);out.put(column.kind()==CellKind.UINT?column.name()+"Token":column.name(),cell instanceof NullCell?null:cell instanceof UIntCell v?Long.toString(v.value()):((TextCell)cell).value());}return Collections.unmodifiableMap(out);}
 private static void page(int limit){require(limit>=1&&limit<=50,INVALID_ARGUMENT);}
 private static Map<String,Object> map(Object... pairs){var values=new LinkedHashMap<String,Object>();for(int n=0;n<pairs.length;n+=2)values.put((String)pairs[n],pairs[n+1]);return Collections.unmodifiableMap(values);}
}
